message.content:
{
  "title": "The Glass Diver's Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers at the ruined gate.",
      "visual_description": "A massive stone gate, cracked and overgrown with thorny vines, stands under a purple sky. The glass diver adjusts his helmet while Mara studies a map. The oracle lamp flickers beside them.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "The sleeping tax collector blocks the path.",
      "visual_description": "A dozing figure slumped against a broken pillar, ledger pages scattered around him like fallen leaves. Mara nudges him but he only snores louder.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts ahead through rubble.",
      "visual_description": "A small metal fox picks its way over collapsed masonry, its blue eyes glowing faintly in the dust. It pauses to sniff the air, tail whirring.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The oracle lamp warns of a cursed tower.",
      "visual_description": "The lamp's flame eye narrows as it casts a trembling light on a leaning tower wrapped in black ivy. Mara marks it on her map with a grim expression.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The glass diver enters a mirror to bypass a locked door.",
      "visual_description": "He presses his helmet against a cracked mirror in an alley; the surface ripples and he steps through, emerging on the other side of a sealed iron gate.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara consults her map under flickering torchlight.",
      "visual_description": "She kneels on cobblestones, compass in hand, as the oracle lamp hovers above. Shadowy battlements loom behind her.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The tin fox discovers a hidden passage.",
      "visual_description": "The fox scratches at a loose stone in a wall; a section slides aside to reveal a dark tunnel. Its ears twitch expectantly.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Armored patrols march through the main square.",
      "visual_description": "Rows of faceless metal figures clank in unison across cracked tiles. The glass diver peers from behind a fallen statue, breath misting his helmet.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver swims through a window into a locked chamber.",
      "visual_description": "He slides through a stained-glass window like water, landing silently in a room filled with old royal banners hanging limp on the walls.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara and the lamp find the tax collector still asleep.",
      "visual_description": "They backtrack to find him now using a stack of stamped papers as a pillow, completely oblivious to the distant clank of patrols.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The tin fox triggers a trap but escapes.",
      "visual_description": "A pressure plate clicks under its paw; a net falls from the ceiling, but the fox sidesteps neatly as the net tangles around a broken pillar.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp reveals a false door.",
      "visual_description": "Its flame casts a shadow that shows the outline of a real door hidden behind an illusion. Mara traces the edges with her fingers.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The glass diver rescues a trapped citizen from a mirror.",
      "visual_description": "He reaches into a shattered mirror and pulls out a frightened figure clutching a torn banner. The figure's face is smudged with dust.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The sleeping tax collector is dragged to safety.",
      "visual_description": "Mara and the glass diver each take an arm and haul the snoring collector out of the path of an approaching patrol. The tin fox scouts ahead.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The group reaches the cursed tower's base.",
      "visual_description": "Black ivy pulses with a faint light. A door made of fused glass stands at the tower's foot. The oracle lamp's flame shivers.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver shatters the glass door with a mirror shard.",
      "visual_description": "He uses a shard from his helmet to strike the door at its weakest point. The door explodes into crystalline dust, revealing a dark stairway.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "All flee across the crumbling bridge.",
      "visual_description": "The rescue team races across a narrow stone bridge that cracks under their feet. The tin fox reaches the far side first, then turns to watch the others.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them.",
      "visual_description": "The last section of bridge falls into the chasm as they stand on safe ground. The glass diver's helmet reflects the distant spires of the ruined city. The oracle lamp glows steady.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ],
  "gate_token": "IRaJPEajAIWoObAo9Z7sKg"
}

